// Two lists in, one list out: the subjects THEY have covered and you have not.
// Matching on whole titles finds nothing, because nobody words a title the same way twice. So
// reduce each title to its meaningful words and compare on the overlap.
const cfg = $('Your topic and theirs').first().json;
const minViews = Number(cfg.minViews) || 0;

const STOP = new Set(['the','a','an','and','or','for','to','in','of','on','with','how','your','you','my','is','it','this','that','best','top','new','2024','2025','2026','vs','from','what','why','free','full','guide','tutorial','video']);
const keywords = (title) => new Set(
  String(title || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter((word) => word.length > 2 && !STOP.has(word))
);
const overlap = (a, b) => {
  let n = 0;
  for (const word of a) if (b.has(word)) n += 1;
  return a.size ? n / a.size : 0;
};

const mine = $('What you already cover').all().map((i) => keywords(i.json.title));
const gaps = [];

for (const item of $('What they cover').all()) {
  const v = item.json;
  const views = Number(v.viewCount || v.views || 0);
  if (views < minViews) continue;                       // ignore what did not work for them either

  const words = keywords(v.title);
  if (words.size < 2) continue;

  // Covered already if any of your videos shares more than half its meaningful words.
  const covered = mine.some((m) => overlap(words, m) > 0.5);
  if (covered) continue;

  gaps.push({
    json: {
      title: v.title,
      views,
      url: v.url || v.videoUrl || '',
      channel: v.channelName || v.channel || '',
      subject: [...words].slice(0, 6).join(' '),
    },
  });
}

// Best-performing gaps first — a subject nobody watched is not a gap worth filling.
gaps.sort((a, b) => b.json.views - a.json.views);
return gaps.slice(0, 25);
